def choose_move(observation):
    def g(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def as_xy(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return (int(v[0]), int(v[1]))
        if isinstance(v, dict):
            if is_num(v.get("x")) and is_num(v.get("y")):
                return (int(v["x"]), int(v["y"]))
            if is_num(v.get("row")) and is_num(v.get("col")):
                return (int(v["col"]), int(v["row"]))
            p = v.get("pos")
            if p is not None:
                return as_xy(p)
            p = v.get("position")
            if p is not None:
                return as_xy(p)
        return None

    def extract_coords(obj, out):
        p = as_xy(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for k in ("positions", "cells", "tiles", "points", "targets", "items", "resources", "enemies", "opponents", "players", "agents", "goals", "hazards", "walls", "blocked", "territory", "claimed", "unclaimed"):
                v = obj.get(k)
                if v is not None:
                    extract_coords(v, out)
            for v in obj.values():
                if isinstance(v, (dict, list, tuple)):
                    extract_coords(v, out)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                if isinstance(v, (dict, list, tuple)):
                    extract_coords(v, out)
                else:
                    p = as_xy(v)
                    if p is not None:
                        out.append(p)

    def dedup(seq):
        seen = set()
        out = []
        for x in seq:
            if x not in seen:
                seen.add(x)
                out.append(x)
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

